[{"order":1,"type":"heading","text":"Mockito JUnit 5 Extension and Annotations (@Mock, @InjectMocks)"},{"order":2,"type":"paragraph","text":"Modern Java unit testing relies heavily on JUnit 5 and Mockito. Integrating Mockito with JUnit 5 using the MockitoExtension eliminates the boilerplate code of manually initializing mocks in setup methods. This tutorial covers how to effectively use the @Mock and @InjectMocks annotations."},{"order":3,"type":"subheading","text":"Prerequisites and Setup"},{"order":4,"type":"paragraph","text":"To use Mockito with JUnit 5, ensure your project includes the necessary dependencies for JUnit 5 Jupiter and Mockito JUnit Jupiter. If you are using Maven, add the mockito-junit-jupiter artifact to your pom.xml file."},{"order":5,"type":"code","text":"<dependency>
    <groupId>org.mockito</groupId>
    <artifactId>mockito-junit-jupiter</artifactId>
    <version>5.11.0</version>
    <scope>test</scope>
</dependency>"},{"order":6,"type":"subheading","text":"Understanding @ExtendWith(MockitoExtension.class)"},{"order":7,"type":"paragraph","text":"In JUnit 4, you used MockitoAnnotations.openMocks(this) inside a @BeforeEach method. In JUnit 5, you enable Mockito annotations by annotating your test class with @ExtendWith(MockitoExtension.class). This extension automatically initializes mocks and handles strict stubbing checks."},{"order":8,"type":"subheading","text":"Using @Mock and @InjectMocks"},{"order":9,"type":"bullet_point","text":"@Mock: Creates a dummy implementation (mock) of a class or interface. You can define its behavior using when().thenReturn()."},{"order":10,"type":"bullet_point","text":"@InjectMocks: Creates an instance of the class and injects the fields annotated with @Mock into the corresponding constructor, setter, or field references."},{"order":11,"type":"subheading","text":"Complete Code Example"},{"order":12,"type":"paragraph","text":"Consider a service class UserService that depends on a UserRepository. Below is how you write a clean JUnit 5 test using Mockito annotations."},{"order":13,"type":"code","text":"import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
public class UserServiceTest {

    @Mock
    private UserRepository userRepository;

    @InjectMocks
    private UserService userService;

    @Test
    public void testFindUserById() {
        // Arrange
        User mockUser = new User(1L, "John Doe");
        when(userRepository.findById(1L)).thenReturn(mockUser);

        // Act
        User result = userService.getUser(1L);

        // Assert
        assertEquals("John Doe", result.getName());
    }
}"},{"order":14,"type":"subheading","text":"Best Practices"},{"order":15,"type":"bullet_point","text":"Always use @ExtendWith(MockitoExtension.class) instead of manual initialization to keep your test lifecycle clean."},{"order":16,"type":"bullet_point","text":"Prefer constructor injection in your production classes as it works seamlessly with @InjectMocks without requiring setters or field-level reflection."},{"order":17,"type":"bullet_point","text":"Keep your unit tests isolated by avoiding unnecessary shared mock states between test methods."}]
